const finalCandidates = [
  ["kalbarri","Kalbarri","AU","Australia","oceania",["western-australia","oceania"],"Australia/Perth",86,["coast","outback","dark-sky","national-park"],"Kalbarri Western Australia",["kalbarri-town","Kalbarri",-27.711,114.165],[["kalbarri-skywalk-night","Kalbarri Skywalk",-27.823,114.473,150,"national-park-skywalk","limited",68,"https://www.kalbarri.org.au/see-do/kalbarri-skywalk"],["meanarra-hill-lookout","Meanarra Hill lookout",-27.694,114.174,190,"hilltop-lookout","limited",66,"https://exploreparks.dbca.wa.gov.au/site/meanarra-hill-lookout"]],["https://www.kalbarri.org.au/see-do/kalbarri-skywalk","https://exploreparks.dbca.wa.gov.au/park/kalbarri-national-park","https://www.emergency.wa.gov.au/"],"Kalbarri after sunset without treating the gorge as a night trail","Kalbarri nach Sonnenuntergang ohne die Schlucht zum Nachtweg zu machen","Kalbarri offers an unusually open western sky, but the national-park gorge remains a hot, remote environment. The Skywalk can support a carefully checked visit from its established platform. Meanarra Hill keeps the alternative closer to town.","Kalbarri bietet einen ungewöhnlich offenen Westhimmel, doch die Nationalparkschlucht bleibt heiß und abgelegen. Der Skywalk kann nach sorgfältiger Prüfung von seiner festen Plattform genutzt werden. Meanarra Hill hält die Alternative näher am Ort.","Heat, fire, road closures, unlit structures and the distance from help make current park and emergency notices essential.","Hitze, Feuer, Straßensperren, unbeleuchtete Anlagen und die Entfernung zu Hilfe machen aktuelle Park- und Notfallmeldungen unverzichtbar.","Visit the Skywalk in daylight first, return only if current access permits it and stay entirely on the built platform and car-park route.","Besuche den Skywalk zuerst bei Tageslicht, kehre nur bei aktuell erlaubtem Zugang zurück und bleibe vollständig auf Plattform und Parkplatzweg.","Do not enter gorge trails at night, feed wildlife or use bright lights across other visitors and the Murchison landscape.","Betrete nachts keine Schluchtwege, füttere keine Tiere und richte kein helles Licht auf Besucher oder die Murchison-Landschaft.","Any access doubt shifts the session to Meanarra or the town edge after a separate check, never to an unsigned gorge track.","Jeder Zugangszweifel verlagert die Sitzung nach separater Prüfung zu Meanarra oder an den Ortsrand, niemals auf einen unmarkierten Schluchtweg."],
  ["river-murray","River Murray","AU","Australia","oceania",["south-australia","oceania"],"Australia/Adelaide",85,["river","dark-sky","low-elevation","road-trip"],"River Murray Dark Sky Reserve South Australia",["mannum","Mannum",-34.912,139.313],[["big-bend-astro-pad","Big Bend astronomy pad",-34.633067,139.665983,45,"astronomy-pad","yes",82,"https://www.rivermurraydarkskyreserve.org/visit"],["towitta-astro-pad","Towitta astronomy pad",-34.524117,139.24845,105,"astronomy-pad","yes",80,"https://www.rivermurraydarkskyreserve.org/visit"]],["https://www.rivermurraydarkskyreserve.org/visit","https://www.rivermurraydarkskyreserve.org/","https://www.parks.sa.gov.au/know-before-you-go"],"One River Murray astro pad and no late river crossing","Ein River-Murray-Astro-Pad ohne späte Flussquerung","The River Murray reserve has an advantage many large dark-sky regions lack. Its published astronomy pads make the destination precise. Big Bend opens toward rural sky east of the river. Towitta suits a western approach; they should not become two stops in one tired night.","Das River-Murray-Reservat besitzt einen Vorteil, der vielen großen Dark-Sky-Regionen fehlt. Seine veröffentlichten Astronomie-Pads machen das Ziel präzise. Big Bend öffnet den ländlichen Himmel östlich des Flusses. Towitta passt zu einer westlichen Anfahrt. Beide gehören nicht in eine müde Nacht.","Ferry schedules, river fog, livestock, heat and long rural roads determine which side of the Murray should be chosen.","Fährzeiten, Flussnebel, Weidetiere, Hitze und lange Landstraßen bestimmen, welche Seite des Murray gewählt wird.","Select Big Bend or Towitta from the accommodation route, reach it before dusk and return without adding a ferry or cross-reserve detour.","Wähle Big Bend oder Towitta nach der Unterkunftsroute, erreiche den Ort vor der Dämmerung und kehre ohne Fähre oder Umweg durch das Reservat zurück.","Use the astronomy pad footprint, close gates, avoid crops and stock and keep vehicle lights pointed away from observers.","Nutze die Fläche des Astronomy Pads, schließe Tore, meide Felder und Tiere und richte Fahrzeuglicht von Beobachtern weg.","Fog or a missed ferry is solved by staying on the current riverbank, not by accelerating through unfamiliar rural roads.","Nebel oder eine verpasste Fähre werden durch Verbleib am aktuellen Ufer gelöst, nicht durch schnelleres Fahren auf unbekannten Landstraßen."],
  ["great-barrier-island","Aotea Great Barrier Island","NZ","New Zealand","oceania",["auckland-region","oceania"],"Pacific/Auckland",92,["island","dark-sky-sanctuary","coast","remote"],"Aotea Great Barrier Island New Zealand",["claris-aotea","Claris",-36.242,175.472],[["medlands-beach-night","Medlands Beach",-36.263,175.496,5,"beach","yes",76,"https://www.greatbarrier.co.nz/dark-sky-sanctuary/"],["windy-canyon-aotea","Windy Canyon trailhead",-36.199,175.447,210,"trailhead","limited",52,"https://www.doc.govt.nz/parks-and-recreation/places-to-go/auckland/places/great-barrier-island-aotea/"]],["https://www.greatbarrier.co.nz/dark-sky-sanctuary/","https://www.doc.govt.nz/parks-and-recreation/places-to-go/auckland/places/great-barrier-island-aotea/","https://www.aucklandcouncil.govt.nz/parks-recreation/Pages/default.aspx"],"Aotea from a beach you already know in daylight","Aotea von einem Strand, den du bei Tageslicht kennst","Aotea's sanctuary status describes island-wide darkness, not permission to enter every beach, track or property at night. Medlands is the simpler independent setting when tide, access and accommodation are nearby. Windy Canyon remains a daylight hiking route unless current local guidance explicitly supports the intended use.","Aoteas Sanctuary-Status beschreibt inselweite Dunkelheit und keine Erlaubnis, jeden Strand, Weg oder jedes Grundstück nachts zu betreten. Medlands ist einfacher, wenn Tide, Zugang und Unterkunft nahe liegen. Windy Canyon bleibt eine Tageswanderroute, solange aktuelle lokale Hinweise die geplante Nutzung nicht ausdrücklich tragen.","Ferry and flight disruption, tides, rough roads, limited services and conservation rules make the island plan dependent on preparation before arrival.","Fähr- und Flugausfälle, Tide, raue Straßen, begrenzte Services und Naturschutzregeln machen den Inselplan von Vorbereitung vor der Ankunft abhängig.","Stay near Claris or Medlands, inspect the beach access at low-risk daylight and keep the night session above the active tide line.","Übernachte nahe Claris oder Medlands, prüfe den Strandzugang bei sicherem Tageslicht und halte die Nachtsitzung oberhalb der aktiven Flutlinie.","Protect nesting birds, dunes and residents' privacy, carry all waste and use no open flame on the beach.","Schütze brütende Vögel, Dünen und die Privatsphäre der Bewohner, nimm allen Abfall mit und nutze kein offenes Feuer am Strand.","Bad marine weather means observing briefly near the booked accommodation, not attempting an unfamiliar island road or coastal track.","Schlechtes Seewetter bedeutet kurze Beobachtung nahe der Unterkunft statt einer unbekannten Inselstraße oder Küstenroute."],
  ["wairarapa","Wairarapa","NZ","New Zealand","oceania",["north-island","oceania"],"Pacific/Auckland",91,["dark-sky-reserve","farmland","southern-sky","accessible"],"Wairarapa New Zealand",["martinborough","Martinborough",-41.219,175.46],[["star-safari-wairarapa","Star Safari",-41.1425,175.5175,90,"private-observatory","limited",82,"https://star-safari.nz/"],["stonehenge-aotearoa-night","Stonehenge Aotearoa",-40.996,175.676,170,"astronomy-centre","limited",78,"https://stonehenge-aotearoa.nz/" ]],["https://wairarapadarksky.nz/","https://star-safari.nz/","https://stonehenge-aotearoa.nz/"],"A booked Wairarapa astronomy evening, not a farm-gate search","Ein gebuchter Astronomieabend in Wairarapa statt Suche am Farmtor","Wairarapa combines a certified reserve with working farms and two established visitor experiences. Star Safari provides a hosted small-group setting. Stonehenge Aotearoa offers a different cultural and astronomical programme. Neither turns surrounding private land into public observing space.","Wairarapa verbindet ein zertifiziertes Reservat mit aktiven Farmen und zwei etablierten Besuchserlebnissen. Star Safari bietet eine betreute Kleingruppe. Stonehenge Aotearoa folgt einem anderen kulturellen und astronomischen Programm. Keines macht umliegendes Privatland zur öffentlichen Beobachtungsfläche.","Booking status, rural road visibility, livestock and changeable North Island weather decide whether the evening can proceed.","Buchungsstatus, Sicht auf Landstraßen, Weidetiere und wechselhaftes Nordinselwetter entscheiden, ob der Abend stattfinden kann.","Choose one dated programme near Martinborough, arrive early enough to find the entrance and return directly after the host closes the session.","Wähle ein terminiertes Programm nahe Martinborough, komme früh genug für die Einfahrt und kehre nach Ende der Sitzung direkt zurück.","Respect hosts, gates, neighbours and farm biosecurity; do not stop on private verges to extend a paid session.","Respektiere Gastgeber, Tore, Nachbarn und Farm-Biosicherheit. Halte nicht auf privaten Seitenstreifen, um eine gebuchte Sitzung zu verlängern.","A weather cancellation becomes a local indoor evening or a new booking, not an unsupported attempt on another farm road.","Eine wetterbedingte Absage wird zu einem lokalen Innenabend oder neuer Buchung und nicht zu einem unbestätigten Versuch auf einer anderen Farmstraße."],
  ["kaikoura","Kaikōura","NZ","New Zealand","oceania",["south-island","oceania"],"Pacific/Auckland",88,["coast","dark-sky-sanctuary","mountains","southern-sky"],"Kaikoura New Zealand",["kaikoura-town","Kaikōura",-42.4,173.681],[["south-bay-kaikoura","South Bay recreation area",-42.429,173.681,8,"coastal-recreation-area","yes",74,"https://kaikouradarksky.nz/"],["point-kean-night-area","Point Kean car park",-42.423,173.71,5,"coastal-car-park","limited",64,"https://www.doc.govt.nz/parks-and-recreation/places-to-go/marlborough/places/kaikoura-area/" ]],["https://kaikouradarksky.nz/","https://www.doc.govt.nz/parks-and-recreation/places-to-go/marlborough/places/kaikoura-area/","https://www.kaikoura.govt.nz/our-district/dark-sky"],"Kaikōura between mountain weather and a live shoreline","Kaikōura zwischen Bergwetter und lebendiger Küste","Kaikōura's darkness is framed by mountains and ocean, which makes the horizon memorable and the shoreline dynamic. South Bay offers a broad established recreation area. Point Kean requires extra care around seals, tide, track limits and current parking rules.","Kaikōuras Dunkelheit wird von Bergen und Meer gerahmt. Das macht den Horizont eindrucksvoll und die Küste dynamisch. South Bay bietet eine breite etablierte Freizeitfläche. Point Kean verlangt besondere Vorsicht bei Robben, Tide, Weggrenzen und aktuellen Parkregeln.","Marine fog, strong wind, earthquake-related closures, wildlife and waves can alter access faster than a monthly climate score suggests.","Seenebel, starker Wind, erdbebenbedingte Sperren, Wildtiere und Wellen können den Zugang schneller verändern, als ein Monatswert vermuten lässt.","Use South Bay as the default, mark the vehicle and safe water boundary before twilight and avoid moving around the peninsula after dark.","Nutze South Bay als Standard, erkenne Fahrzeug und sichere Wassergrenze vor der Dämmerung und wechsle nachts nicht um die Halbinsel.","Give seals generous distance, stay out of nesting and tidal areas and keep the recreation route clear.","Halte großen Abstand zu Robben, bleibe aus Brut- und Gezeitenflächen und halte die Freizeitrouten frei.","Fog or high wind moves the evening back to town; the mountain side is not an automatic escape from coastal conditions.","Nebel oder starker Wind verlagern den Abend in den Ort. Die Bergseite ist kein automatischer Ausweg aus Küstenbedingungen."],
  ["oudtshoorn","Oudtshoorn","ZA","South Africa","africa",["western-cape","africa"],"Africa/Johannesburg",84,["semi-desert","southern-sky","private-reserve","dry"],"Oudtshoorn Klein Karoo South Africa",["oudtshoorn-town","Oudtshoorn",-33.59,22.202],[["buffelsdrift-night-experience","Buffelsdrift Game Lodge",-33.516,22.244,340,"private-reserve-lodge","limited",76,"https://www.buffelsdrift.com/activities/stargazing/"],["de-zeekoe-night-area","De Zeekoe farm stay",-33.66,22.196,310,"farm-stay","limited",68,"https://dezeekoe.co.za/"]],["https://www.buffelsdrift.com/activities/stargazing/","https://dezeekoe.co.za/","https://www.oudtshoorn.com/"],"Klein Karoo stars inside a booked property","Klein-Karoo-Sterne innerhalb eines gebuchten Grundstücks","Oudtshoorn's dry interior sky is attractive, but the most responsible night access is tied to a host. Buffelsdrift advertises a guided stargazing activity. De Zeekoe can support a quieter stay-based session only with direct permission for the exact area.","Oudtshoorns trockener Binnenhimmel ist attraktiv, doch der verantwortungsvollste Nachtzugang ist an einen Gastgeber gebunden. Buffelsdrift bietet eine geführte Stargazing-Aktivität an. De Zeekoe kann eine ruhigere, unterkunftsgebundene Sitzung nur mit direkter Erlaubnis für die genaue Fläche tragen.","Wildlife, private farm boundaries, gravel roads, summer heat and programme availability rule out casual roadside observation.","Wildtiere, private Farmgrenzen, Schotterstraßen, Sommerhitze und Programmverfügbarkeit schließen beiläufige Straßenrandbeobachtung aus.","Book the lodge or farm first, confirm the meeting point and keep the entire evening within the host's lit and unlit movement rules.","Buche Lodge oder Farm zuerst, bestätige den Treffpunkt und halte den ganzen Abend innerhalb der Bewegungs- und Lichtregeln des Gastgebers.","Follow every wildlife instruction, use no food or flash outside approved areas and never leave the property route alone at night.","Befolge alle Wildtierhinweise, nutze außerhalb erlaubter Flächen weder Essen noch Blitz und verlasse die Grundstücksroute nachts nie allein.","If the host cancels for weather or wildlife, remain at the accommodation and reschedule instead of searching farm roads.","Sagt der Gastgeber wegen Wetter oder Wildtieren ab, bleibe in der Unterkunft und buche neu, statt Farmstraßen abzusuchen."],
  ["headlands-michigan","Headlands","US","United States","north-america",["michigan","north-america"],"America/Detroit",82,["lake","dark-sky-park","accessible","forest"],"Headlands Dark Sky Park Michigan",["mackinaw-city","Mackinaw City",45.777,-84.727],[["headlands-waterfront-event-center","Headlands waterfront viewing area",45.779,-84.782,185,"dark-sky-park","yes",82,"https://www.midarkskypark.org/visit/"],["mcgulpin-point","McGulpin Point",45.787,-84.773,180,"lighthouse-grounds","limited",66,"https://www.mcgulpinpoint.org/" ]],["https://www.midarkskypark.org/visit/","https://www.midarkskypark.org/programs-events/","https://www.mcgulpinpoint.org/"],"A Headlands night that stays inside the county park","Eine Headlands-Nacht innerhalb des County Parks","Headlands is a purpose-built dark-sky destination near Mackinaw City, which removes the need to hunt for a Lake Michigan pull-out. Its waterfront viewing area is the default. McGulpin Point is a separate historic property whose hours and permissions must be checked independently.","Headlands ist ein eigens ausgewiesenes Dark-Sky-Ziel nahe Mackinaw City. Dadurch entfällt die Suche nach einer Haltebucht am Lake Michigan. Die Ufer-Beobachtungsfläche ist der Standard. McGulpin Point ist ein separates historisches Grundstück mit eigenen Zeiten und Erlaubnissen.","Lake weather, snow, shoreline ice, event crowds and parking instructions determine the practical visit.","Seewetter, Schnee, Ufervereisung, Veranstaltungsandrang und Parkhinweise bestimmen den praktischen Besuch.","Check the Headlands programme, arrive before the darkest period and remain on the county park's signed path between parking and water.","Prüfe das Headlands-Programm, komme vor der dunkelsten Phase und bleibe auf dem beschilderten Weg des County Parks zwischen Parkplatz und Wasser.","Keep the shoreline and event routes open, use no bright flash and respect all quiet and facility rules.","Halte Ufer und Veranstaltungswege frei, nutze keinen hellen Blitz und respektiere Ruhe- sowie Anlagenregeln.","Ice, wind or a full event should move the session back to Mackinaw City rather than to an unverified lakeshore.","Eis, Wind oder eine volle Veranstaltung verlagern die Sitzung nach Mackinaw City statt an ein unbestätigtes Seeufer."],
  ["wadi-rum","Wadi Rum","JO","Jordan","asia",["aqaba","asia"],"Asia/Amman",93,["desert","unesco","guided","remote"],"Wadi Rum Jordan",["wadi-rum-village","Wadi Rum Village",29.574,35.422],[["wadi-rum-visitor-centre","Wadi Rum Visitor Centre",29.64,35.434,930,"protected-area-gateway","limited",66,"https://wadirum.jo/"],["wadi-rum-booked-camp","Booked Wadi Rum desert camp",29.56,35.43,980,"desert-camp","limited",72,"https://international.visitjordan.com/Wheretogo/Wadi-Rum"]],["https://wadirum.jo/","https://international.visitjordan.com/Wheretogo/Wadi-Rum","https://whc.unesco.org/en/list/1377/"],"Wadi Rum astronomy from a booked camp, not an open map pin","Wadi-Rum-Astronomie vom gebuchten Camp statt von einem Kartenpunkt","Wadi Rum is a protected desert landscape where a map coordinate cannot replace a registered local arrangement. The visitor centre is the gateway, not the overnight observing field. A booked camp or guide should define transport, the exact place and the return.","Wadi Rum ist eine geschützte Wüstenlandschaft, in der ein Kartenpunkt keine registrierte lokale Regelung ersetzt. Das Besucherzentrum ist das Tor und nicht das nächtliche Beobachtungsfeld. Ein gebuchtes Camp oder ein Guide definiert Transport, genauen Ort und Rückkehr.","Heat, cold, sand, flash floods, navigation and protected-area rules make independent night driving unsuitable.","Hitze, Kälte, Sand, Sturzfluten, Navigation und Schutzgebietsregeln machen unabhängiges Nachtfahren ungeeignet.","Register at the visitor centre, meet the confirmed operator and observe only from the camp or stop selected for that itinerary.","Registriere dich am Besucherzentrum, triff den bestätigten Anbieter und beobachte nur vom Camp oder Stopp des gebuchten Plans.","Respect Bedouin hosts, archaeology and quiet; leave no waste and never drive or walk away from the agreed route.","Respektiere beduinische Gastgeber, Archäologie und Ruhe. Hinterlasse keinen Abfall und entferne dich nie fahrend oder gehend von der vereinbarten Route.","Wind, flood risk or a cancelled booking means staying in Wadi Rum Village or Aqaba, not hiring an informal night drive.","Wind, Sturzflutrisiko oder stornierte Buchung bedeuten Aufenthalt in Wadi Rum Village oder Aqaba und keine informelle Nachtfahrt."],
  ["jaisalmer","Jaisalmer","IN","India","asia",["rajasthan","asia"],"Asia/Kolkata",85,["desert","guided","culture","dry"],"Jaisalmer Thar Desert India",["jaisalmer-city","Jaisalmer",26.9157,70.9083],[["sam-sand-dunes-camp-zone","Sam Sand Dunes camp zone",26.838,70.536,225,"desert-tourism-zone","limited",66,"https://www.tourism.rajasthan.gov.in/jaisalmer.html"],["khuri-village-camp-zone","Khuri village camp zone",26.619,70.723,230,"desert-village","limited",64,"https://www.incredibleindia.gov.in/en/rajasthan/jaisalmer"]],["https://www.tourism.rajasthan.gov.in/jaisalmer.html","https://www.incredibleindia.gov.in/en/rajasthan/jaisalmer","https://jaisalmer.rajasthan.gov.in/"],"A Thar Desert night with transport agreed in advance","Eine Thar-Wüstennacht mit vorab geklärtem Transport","Jaisalmer's desert sky is inseparable from camp quality, transport and the chosen tourism zone. Sam is busy and easy to book. Khuri can feel quieter, but it still requires a confirmed host and vehicle rather than independent movement onto dunes.","Jaisalmers Wüstenhimmel ist untrennbar mit Campqualität, Transport und der gewählten Tourismuszone verbunden. Sam ist belebt und leicht buchbar. Khuri kann ruhiger wirken, verlangt aber ebenfalls einen bestätigten Gastgeber und ein Fahrzeug statt unabhängiger Bewegung auf Dünen.","Heat, cold, sand, traffic, informal sales and poorly specified camp locations can undermine both safety and darkness.","Hitze, Kälte, Sand, Verkehr, informeller Verkauf und ungenau beschriebene Camp-Lagen können Sicherheit und Dunkelheit beeinträchtigen.","Book a named camp with round-trip transport from Jaisalmer, confirm the exact dune zone and keep the observing period inside the hosted programme.","Buche ein benanntes Camp mit Hin- und Rücktransport ab Jaisalmer, bestätige die genaue Dünenzone und halte die Beobachtung innerhalb des betreuten Programms.","Avoid driving over vegetation, leave no plastic or food waste and respect village, livestock and cultural boundaries.","Fahre nicht über Vegetation, hinterlasse weder Plastik noch Essensreste und respektiere Dorf-, Tier- und Kulturgrenzen.","An unclear operator, dust storm or transport change is reason to remain in Jaisalmer and rebook through a traceable provider.","Ein unklarer Anbieter, Staubsturm oder Transportwechsel ist Grund, in Jaisalmer zu bleiben und bei einem nachvollziehbaren Anbieter neu zu buchen."],
  ["aenos","Mount Aenos","GR","Greece","europe",["ionian-islands","europe"],"Europe/Athens",82,["island","mountain","dark-sky-park","forest"],"Mount Aenos Kefalonia Greece",["sami-kefalonia","Sami, Kefalonia",38.25,20.646],[["aenos-entrance-view-area","Mount Aenos entrance viewing area",38.162,20.663,1120,"national-park-entrance","limited",68,"https://aenosnationalpark.gr/en/"],["aenos-picnic-area","Mount Aenos picnic area",38.189,20.63,930,"forest-picnic-area","limited",62,"https://aenosnationalpark.gr/en/activities/"]],["https://aenosnationalpark.gr/en/","https://aenosnationalpark.gr/en/activities/","https://darksky.org/places/aenos-dark-sky-park/"],"Mount Aenos with the forest road settled before dusk","Mount Aenos mit geklärter Waldstraße vor der Dämmerung","Mount Aenos brings a dark mountain into an island holiday, but the fir forest and park road require more discipline than a coastal viewpoint. The entrance area is the safer independent reference. Interior picnic areas depend on explicit current access.","Mount Aenos bringt einen dunklen Berg in einen Inselurlaub, doch Tannenwald und Parkstraße verlangen mehr Disziplin als ein Küstenaussichtspunkt. Der Eingangsbereich ist die sicherere unabhängige Referenz. Innere Picknickflächen hängen von ausdrücklich aktuellem Zugang ab.","Fire restrictions, wind, fog, road gates and forest navigation can close the useful night window even under clear coastal skies.","Feuerbeschränkungen, Wind, Nebel, Straßentore und Waldnavigation können das nutzbare Nachtfenster trotz klarer Küste schließen.","Check the park on the travel day, inspect the entrance area in daylight and descend on the same route before fatigue builds.","Prüfe den Park am Reisetag, erkunde den Eingangsbereich bei Tageslicht und fahre auf derselben Route ab, bevor Müdigkeit wächst.","Use no flame, protect the endemic fir forest, keep roads open and follow every seasonal fire instruction.","Nutze kein Feuer, schütze den endemischen Tannenwald, halte Straßen frei und befolge alle saisonalen Feuerhinweise.","A closed gate or rising wind redirects the evening to a legal coastal area near the accommodation, not deeper into the forest.","Ein geschlossenes Tor oder stärkerer Wind verlagert den Abend an eine legale Küstenfläche nahe der Unterkunft und nicht tiefer in den Wald."],
];

for (const row of finalCandidates) {
  const [id,name,countryCode,countryName,continent,regions,timezone,priority,tags,affiliateQuery,stay,sites,urls,titleEn,titleDe,openingEn,openingDe,constraintEn,constraintDe,routeEn,routeDe,conductEn,conductDe,fallbackEn,fallbackDe] = row;
  candidates.push({ id,name,countryCode,countryName,continent,regions,timezone,priority,tags,affiliateQuery,stay,sites,
    source: [["Official destination authority",`${name} destination guidance`,urls[0],"official-destination"],["Protected-area or visitor authority",`${name} access guidance`,urls[1],"protected-area"],["Public or nonprofit authority",`${name} status and context`,urls[2],"nonprofit-certifier"]],
    title: bi(titleEn,titleDe), opening: bi(openingEn,openingDe), constraint: bi(constraintEn,constraintDe), route: bi(routeEn,routeDe), conduct: bi(conductEn,conductDe), fallback: bi(fallbackEn,fallbackDe) });
}

if (candidates.length !== 25) throw new Error(`Catalog expansion requires 25 candidates, found ${candidates.length}`);

const sourceIds = (item) => [`${item.id}-place`, `${item.id}-access`, `${item.id}-status`];
const sourceRecords = (item) => item.source.map(([publisher, title, url, authority], index) => ({
  id: sourceIds(item)[index], publisher, title, url, checkedAt: "2026-08-31", authority,
}));

function guideFor(item, index) {
  const ids = sourceIds(item);
  const primary = item.sites[0][1];
  const secondary = item.sites[1][1];
  const stayName = item.stay[1];
  const openingTurn = [
    bi(`The practical value of ${item.name} appears when the chosen site, legal access and return journey are treated as one decision.`, `Der praktische Wert von ${item.name} zeigt sich, wenn gewählter Ort, legaler Zugang und Rückweg als eine Entscheidung behandelt werden.`),
    bi(`${item.name} is best understood through the final safe kilometre rather than through a regional darkness label alone.`, `${item.name} lässt sich am besten über den letzten sicheren Kilometer verstehen und nicht allein über ein regionales Dunkelheitslabel.`),
    bi(`A useful night in ${item.name} begins with a precise place and a credible way home.`, `Eine brauchbare Nacht in ${item.name} beginnt mit einem präzisen Ort und einem glaubwürdigen Heimweg.`),
    bi(`Darkness is only one part of the ${item.name} decision.`, `Dunkelheit ist nur ein Teil der Entscheidung für ${item.name}.`),
    bi(`${item.name} rewards restraint because the strongest plan usually uses one site well.`, `${item.name} belohnt Zurückhaltung, weil der stärkste Plan meist einen Ort gut nutzt.`),
  ][index % 5];
  const sectionHeadings = [
    bi(`${primary} sets the shape of the evening`, `${primary} bestimmt die Form des Abends`),
    bi(`The condition that can cancel ${item.name}`, `Die Bedingung, die ${item.name} absagen kann`),
    bi(`A return to ${stayName} without improvisation`, `Rückkehr nach ${stayName} ohne Improvisation`),
  ];
  const standfirst = {
    en: `${item.opening.en} ${openingTurn.en} ${item.constraint.en} The score helps compare months, but it is not tonight's forecast and it does not prove that a road, gate, programme or parking area is open. Check the cited authority again on the travel day.`,
    de: `${item.opening.de} ${openingTurn.de} ${item.constraint.de} Der Wert hilft beim Monatsvergleich, ist aber keine Vorhersage für heute Nacht und beweist weder offene Straße noch Tor, Programm oder Parkplatz. Prüfe die zitierte Stelle am Reisetag erneut.`,
  };
  const editorialAngle = {
    en: `${item.route.en} That concrete route gives ${item.name} more value than a list of scenic pins. ${item.fallback.en}`,
    de: `${item.route.de} Diese konkrete Route gibt ${item.name} mehr Wert als eine Liste schöner Kartenpunkte. ${item.fallback.de}`,
  };
  const sections = [
    {
      id: `${item.id}-place-choice`, heading: sectionHeadings[0], sourceIds: ids,
      paragraphs: {
        en: [
          `${item.opening.en} ${primary} is the recommended site because its role can be explained from published visitor information rather than guessed from satellite imagery. ${secondary} remains a genuine alternative, yet its separate access conditions should be checked before leaving ${stayName}. Treat the two cards on the page as different plans. They are not an invitation to switch sites after dark whenever the first horizon disappoints.`,
          `${openingTurn.en} The useful comparison is therefore practical. Ask whether the car can remain legally, whether the last walking line is obvious, whether the site is compatible with current notices and whether a tired return still feels simple. The astronomical model changes with the selected coordinates, local time and elevation. It does not include cloud, smoke, terrain hidden from the dataset, buildings or temporary closures.`,
        ],
        de: [
          `${item.opening.de} ${primary} ist die Empfehlung, weil seine Rolle aus veröffentlichten Besucherinformationen erklärt werden kann und nicht aus Satellitenbildern geraten wird. ${secondary} bleibt eine echte Alternative, doch seine eigenen Zugangsbedingungen werden vor der Abfahrt aus ${stayName} geprüft. Die beiden Karten auf der Seite stehen für unterschiedliche Pläne und laden nicht dazu ein, nachts wegen eines enttäuschenden Horizonts zu wechseln.`,
          `${openingTurn.de} Der brauchbare Vergleich ist deshalb praktisch. Frage, ob das Auto legal stehen darf, ob der letzte Gehweg eindeutig ist, ob der Ort zu aktuellen Meldungen passt und ob eine müde Rückkehr einfach bleibt. Das astronomische Modell ändert sich mit gewählter Koordinate, Ortszeit und Höhe. Es enthält weder Wolken noch Rauch, verborgene Geländekanten, Gebäude oder temporäre Sperren.`,
        ],
      },
    },
    {
      id: `${item.id}-limiting-condition`, heading: sectionHeadings[1], sourceIds: ids,
      paragraphs: {
        en: [
          `${item.constraint.en} This is the part of the plan that deserves a fresh source check, even when the climatological month ranks well. Read alerts, operating hours, fire or wildlife notices and local weather together. A high score never compensates for an access restriction, unsafe surface or return that depends on reception and an untested road.`,
          `${item.name}'s best-month signal uses historical conditions to identify a useful season. For the actual evening, compare current cloud, wind, temperature, precipitation, smoke where relevant and Moon position. Cancel early when those inputs point in the same poor direction. Waiting at ${stayName} costs less than recovering from a bad late decision at ${primary}.`,
        ],
        de: [
          `${item.constraint.de} Dieser Teil des Plans verdient eine neue Quellenprüfung, selbst wenn der klimatologische Monat gut abschneidet. Lies Meldungen, Betriebszeiten, Feuer- oder Wildtierhinweise und lokales Wetter gemeinsam. Ein hoher Wert gleicht weder eine Zugangsbeschränkung noch unsicheren Untergrund oder eine Rückfahrt aus, die von Empfang und ungetesteter Straße abhängt.`,
          `Das Signal für den besten Monat in ${item.name} nutzt historische Bedingungen, um eine brauchbare Saison zu erkennen. Für den tatsächlichen Abend vergleichst du aktuelle Wolken, Wind, Temperatur, Niederschlag, gegebenenfalls Rauch und die Mondposition. Sage früh ab, wenn diese Eingaben gemeinsam gegen den Plan sprechen. Warten in ${stayName} kostet weniger als die Folgen einer schlechten späten Entscheidung an ${primary}.`,
        ],
      },
    },
    {
      id: `${item.id}-field-rhythm`, heading: sectionHeadings[2], sourceIds: ids,
      paragraphs: {
        en: [
          `${item.route.en} Arrive while signs, edges and the walking surface remain visible. Mark the vehicle, the safe observation footprint and the simplest retreat before opening equipment. A useful session can be short. Dark adaptation and patient naked-eye orientation often reveal more than hurried setup followed by a second drive.`,
          `${item.conduct.en} Pack in a fixed order, count every small item and leave while concentration is still good. ${item.fallback.en} That fallback is part of the route rather than a consolation prize. It protects the destination, the people sharing it and the credibility of a guide that must work beyond a perfect-weather photograph.`,
        ],
        de: [
          `${item.route.de} Komme an, solange Schilder, Kanten und Gehfläche sichtbar bleiben. Merke dir Fahrzeug, sichere Beobachtungsfläche und einfachsten Rückzug, bevor du Ausrüstung öffnest. Eine brauchbare Sitzung darf kurz sein. Dunkeladaption und ruhige Orientierung mit bloßem Auge zeigen oft mehr als hektischer Aufbau mit anschließender zweiter Fahrt.`,
          `${item.conduct.de} Packe in fester Reihenfolge, zähle jedes Kleinteil und fahre, solange die Konzentration gut ist. ${item.fallback.de} Diese Alternative ist Teil der Route und kein Trostpreis. Sie schützt das Ziel, die Menschen dort und die Glaubwürdigkeit eines Guides, der mehr leisten muss als ein Foto bei perfektem Wetter.`,
        ],
      },
    },
  ];
  const stepSpecs = [
    ["proof", bi(`Before leaving ${stayName}`, `Vor der Abfahrt aus ${stayName}`), bi("Confirm the exact access", "Den genauen Zugang bestätigen")],
    ["arrival", bi("While the ground is visible", "Solange der Boden sichtbar ist"), bi(`Read ${primary} in daylight`, `${primary} bei Tageslicht lesen`)],
    ["observe", bi("After full dark", "Nach vollständiger Dunkelheit"), bi("Keep the session inside one footprint", "Die Sitzung auf eine Fläche begrenzen")],
    ["return", bi("Before attention fades", "Bevor die Aufmerksamkeit nachlässt"), bi(`Return directly to ${stayName}`, `Direkt nach ${stayName} zurückkehren`)],
  ];
  const stepBodies = [
    bi(`${item.name} requires a same-day source check. Open all three cited authorities and confirm the status of ${primary}, the route, parking or booking, operating limits and current hazard notices. Save the result and directions offline. If the official information no longer supports the plan, use the stated fallback instead of treating an old page or map pin as permission.`, `${item.name} verlangt eine Quellenprüfung am selben Tag. Öffne alle drei zitierten Stellen und bestätige Status von ${primary}, Route, Parken oder Buchung, Betriebsgrenzen und aktuelle Gefahrenmeldungen. Speichere Ergebnis und Navigation offline. Tragen die offiziellen Informationen den Plan nicht mehr, nutze die genannte Alternative, statt eine alte Seite oder Kartenmarke als Erlaubnis zu verstehen.`),
    bi(`Reach ${primary} early enough to see every boundary that matters. Identify the legal vehicle position, safe walking line, observation surface and quickest retreat. Check wind, temperature and cloud once more before unpacking. Do not extend the route toward ${secondary} merely because time remains.`, `Erreiche ${primary} früh genug, um jede wichtige Grenze zu sehen. Bestimme legalen Fahrzeugplatz, sicheren Gehweg, Beobachtungsfläche und schnellsten Rückzug. Prüfe Wind, Temperatur und Wolken erneut, bevor du auspackst. Verlängere die Route nicht Richtung ${secondary}, nur weil noch Zeit bleibt.`),
    bi(`At ${primary}, let your eyes adapt before deciding what equipment is useful. Keep screens dim, point every lamp down and place bags and tripod legs outside shared movement lines. ${item.conduct.en} The site remains a real place with neighbours, wildlife or protected ground even when the sky becomes the main subject.`, `An ${primary} lässt du die Augen adaptieren, bevor du über Ausrüstung entscheidest. Dimme Bildschirme, richte jedes Licht nach unten und halte Taschen sowie Stativbeine aus gemeinsamen Wegen. ${item.conduct.de} Der Ort bleibt auch dann ein realer Platz mit Nachbarn, Wildtieren oder Schutzflächen, wenn der Himmel zum Hauptmotiv wird.`),
    bi(`Leave ${primary} with enough energy for a slow, predictable return. Pack completely, inspect the ground and use the route already learned in daylight. ${item.fallback.en} Record any access difference for the next visit rather than trying to solve it through a late detour.`, `Verlasse ${primary} mit genug Energie für eine langsame, vorhersehbare Rückkehr. Packe vollständig, prüfe den Boden und nutze die bei Tageslicht gelernte Route. ${item.fallback.de} Notiere Zugangsabweichungen für den nächsten Besuch, statt sie durch einen späten Umweg lösen zu wollen.`),
  ];
  return {
    version: 1, destinationId: item.id, slug: item.id,
    seoTitle: bi(`${item.name} stargazing guide: ${primary}`, `Stargazing-Guide ${item.name}: ${primary}`),
    seoDescription: bi(`Plan a responsible ${item.name} stargazing night at ${primary} with sourced access, current-condition checks and a clear return to ${stayName}.`, `Plane eine verantwortungsvolle Nacht in ${item.name} an ${primary} mit belegtem Zugang, aktueller Prüfung und klarer Rückkehr.`),
    standfirst, editorialAngle, sections,
    tour: {
      title: item.title,
      summary: bi(`${item.route.en} ${item.constraint.en} The route keeps the decision close to ${primary}, with ${stayName} as the known base and ${secondary} reserved for a separately verified plan.`, `${item.route.de} ${item.constraint.de} Die Route hält die Entscheidung nahe ${primary}, mit ${stayName} als bekannter Basis und ${secondary} nur für einen separat geprüften Plan.`),
      duration: bi("One evening with a daylight arrival and direct return", "Ein Abend mit Ankunft bei Tageslicht und direkter Rückkehr"),
      suitability: bi(`For independent visitors who can verify access, weather and the return route before reaching ${primary}; not for improvised night exploration.`, `Für unabhängige Besucher, die Zugang, Wetter und Rückweg vor der Ankunft an ${primary} prüfen können; nicht für spontane Nachterkundung.`),
      sourceIds: ids,
      steps: stepSpecs.map(([suffix,timeHint,title], stepIndex) => ({ id: `${item.id}-${suffix}`, timeHint, title, body: stepBodies[stepIndex], sourceIds: ids })),
    },
    fieldNotesTitle: bi(`Three decisions for ${item.name}`, `Drei Entscheidungen für ${item.name}`),
    fieldNotes: [
      { id: `${item.id}-access-note`, title: bi("Access evidence", "Zugangsnachweis"), body: bi(`${primary} remains usable only while the current authority supports the route described here. Check the dated notice, booking or operating rule and keep it offline. The coordinate positions the sky simulation; it does not grant entry or overnight use.`, `${primary} bleibt nur nutzbar, solange die aktuelle Behörde die hier beschriebene Route trägt. Prüfe datierte Meldung, Buchung oder Betriebsregel und speichere sie offline. Die Koordinate positioniert die Himmelssimulation und gewährt weder Zutritt noch Übernachtung.`), sourceIds: ids },
      { id: `${item.id}-weather-note`, title: bi("The real-night veto", "Das Veto der echten Nacht"), body: bi(`${item.constraint.en} Compare the live forecast and alerts with the historical month ranking. If visibility, surface or return safety is doubtful, the decision is to postpone even when the astronomy panel shows a favourable geometric sky.`, `${item.constraint.de} Vergleiche Live-Vorhersage und Meldungen mit der historischen Monatsrangliste. Sind Sicht, Untergrund oder Rückkehr unsicher, wird verschoben, selbst wenn das Astronomiepanel einen günstigen geometrischen Himmel zeigt.`), sourceIds: ids },
      { id: `${item.id}-fallback-note`, title: bi(`The ${stayName} fallback`, `Die Alternative ${stayName}`), body: bi(`${item.fallback.en} A fallback decided before sunset prevents unsafe bargaining with conditions later. It also keeps private land, protected habitat and quiet local roads from becoming substitutes for a closed or unsuitable official site.`, `${item.fallback.de} Eine vor Sonnenuntergang gewählte Alternative verhindert späteres riskantes Verhandeln mit den Bedingungen. Sie schützt außerdem Privatland, Lebensräume und ruhige lokale Straßen davor, Ersatz für einen geschlossenen oder ungeeigneten offiziellen Ort zu werden.`), sourceIds: ids },
    ],
    faq: [
      { question: bi(`Is ${primary} open every night?`, `Ist ${primary} jede Nacht geöffnet?`), answer: bi(`${primary} has no permanent access guarantee. Use the cited authority to check the actual date, including gates, programmes, parking, seasonal limits and emergency notices. ${item.route.en} If a rule is unclear, contact the operator or protected-area authority before travel rather than interpreting silence as permission.`, `Für ${primary} gibt es keine dauerhafte Zugangsgarantie. Prüfe das tatsächliche Datum bei der zitierten Stelle, einschließlich Toren, Programmen, Parken, Saisonlimits und Notfallmeldungen. ${item.route.de} Ist eine Regel unklar, kontaktiere Betreiber oder Schutzgebietsverwaltung vor der Reise und deute Schweigen nicht als Erlaubnis.`), sourceIds: ids },
      { question: bi(`Does the ${item.name} score predict tonight's sky?`, `Sagt der ${item.name}-Wert den Himmel heute Nacht voraus?`), answer: bi(`${item.name}'s monthly score summarises historical climate, darkness, elevation and access inputs. The astronomical panel calculates Sun, Moon and star geometry for the selected site and time. Neither replaces a live cloud, wind, smoke, road or safety check. ${item.constraint.en}`, `Der Monatswert für ${item.name} fasst historische Klima-, Dunkelheits-, Höhen- und Zugangsdaten zusammen. Das Astronomiepanel berechnet Sonne, Mond und Sterngeometrie für Ort und Zeit. Beides ersetzt keine Live-Prüfung von Wolken, Wind, Rauch, Straße oder Sicherheit. ${item.constraint.de}`), sourceIds: ids },
    ],
    sources: sourceRecords(item), lastReviewedAt: "2026-08-31",
  };
}

function tourFor(item, index) {
  const ids = sourceIds(item);
  const primary = item.sites[0][1];
  const secondary = item.sites[1][1];
  const stayName = item.stay[1];
  const orders = [
    ["decisions", "prose", "schedule", "note"],
    ["prose", "schedule", "decisions", "note"],
    ["schedule", "note", "prose", "decisions"],
    ["note", "decisions", "schedule", "prose"],
  ];
  const blocks = {
    prose: { id: `${item.id}-tour-ground`, kind: "prose", heading: bi(`Why ${primary} is enough for one night`, `Warum ${primary} für eine Nacht genügt`), paragraphs: {
      en: [`${item.opening.en} This tour commits to ${primary} because a single known site preserves attention for the sky and the return. ${secondary} is useful information for another date, not a target to add after darkness.`, `${item.conduct.en} Spend the first unlit minutes identifying cardinal directions and the broadest open horizon. Equipment should serve that observation rather than turning the evening into a complicated setup exercise.`],
      de: [`${item.opening.de} Diese Tour legt sich auf ${primary} fest, weil ein bekannter Ort Aufmerksamkeit für Himmel und Rückweg erhält. ${secondary} ist nützliche Information für ein anderes Datum und kein Ziel, das nach Einbruch der Dunkelheit ergänzt wird.`, `${item.conduct.de} Nutze die ersten unbeleuchteten Minuten für Himmelsrichtungen und den offensten Horizont. Ausrüstung dient dieser Beobachtung, statt den Abend in eine komplizierte Aufbauübung zu verwandeln.`],
    }, sourceIds: ids },
    note: { id: `${item.id}-tour-veto`, kind: "note", heading: bi(`What cancels the ${item.name} route`, `Was die Route in ${item.name} absagt`), body: bi(`${item.constraint.en} Treat that limit as a decision made before equipment leaves the vehicle. ${item.fallback.en} A shorter evening is a successful outcome when it prevents an exposed or unsupported return.`, `${item.constraint.de} Behandle diese Grenze als Entscheidung, bevor Ausrüstung das Fahrzeug verlässt. ${item.fallback.de} Ein kürzerer Abend ist erfolgreich, wenn er eine exponierte oder ungesicherte Rückkehr verhindert.`), sourceIds: ids, tone: "warning" },
    decisions: { id: `${item.id}-tour-choices`, kind: "decisions", heading: bi(`Two choices before leaving ${stayName}`, `Zwei Entscheidungen vor der Abfahrt aus ${stayName}`), introduction: bi("The route works only when access and conditions agree.", "Die Route funktioniert nur, wenn Zugang und Bedingungen übereinstimmen."), items: [
      { label: bi(`${primary} is confirmed`, `${primary} ist bestätigt`), body: bi(`For ${primary}, use the published route, arrive in daylight and keep the session at the selected site. Save the source and return directions offline so poor reception cannot change the agreed boundary.`, `Für ${primary} nutzt du die veröffentlichte Route, kommst bei Tageslicht und bleibst am gewählten Ort. Speichere Quelle und Rückweg offline, damit schlechter Empfang die vereinbarte Grenze nicht verändert.`), sourceIds: ids },
      { label: bi("Any essential detail is uncertain", "Ein wesentliches Detail ist unsicher"), body: bi(`${item.fallback.en} Do not substitute ${secondary} unless its own authority, route and timing have been checked before departure.`, `${item.fallback.de} Ersetze den Ort nicht durch ${secondary}, solange dessen eigene Behörde, Route und Zeit nicht vor der Abfahrt geprüft wurden.`), sourceIds: ids },
    ] },
    schedule: { id: `${item.id}-tour-timing`, kind: "schedule", heading: bi(`The evening rhythm at ${primary}`, `Der Abendrhythmus an ${primary}`), introduction: bi("Timing is built around visibility on arrival and attention on return.", "Die Zeitplanung richtet sich nach Sicht bei Ankunft und Aufmerksamkeit bei Rückkehr."), items: [
      { time: bi("Before sunset", "Vor Sonnenuntergang"), title: bi("Learn the last kilometre", "Den letzten Kilometer lernen"), body: bi(`Travel from ${stayName}, inspect the legal parking position, safe observation area and retreat while all surfaces are visible. Recheck current conditions before committing to the session.`, `Fahre aus ${stayName}, prüfe legalen Parkplatz, sichere Beobachtungsfläche und Rückzug, solange alle Flächen sichtbar sind. Prüfe aktuelle Bedingungen erneut, bevor du dich auf die Sitzung festlegst.`), sourceIds: ids },
      { time: bi("After darkness", "Nach Einbruch der Dunkelheit"), title: bi("Observe before adding equipment", "Vor zusätzlicher Ausrüstung beobachten"), body: bi(`At ${primary}, allow full dark adaptation, orient with the naked eye and add only equipment that can be managed without obstructing anyone. Keep the setup inside the footprint inspected earlier.`, `An ${primary} lässt du die Augen vollständig adaptieren, orientierst dich mit bloßem Auge und ergänzt nur Ausrüstung, die ohne Behinderung anderer nutzbar ist. Halte den Aufbau innerhalb der zuvor geprüften Fläche.`), sourceIds: ids },
      { time: bi("At the planned stop time", "Zur geplanten Endzeit"), title: bi("Leave on the known route", "Auf der bekannten Route fahren"), body: bi(`Leave ${primary} systematically, inspect the ground and return directly to ${stayName}. Do not trade a safe finish for a late move toward ${secondary} or an unverified roadside horizon.`, `Verlasse ${primary} systematisch, prüfe den Boden und kehre direkt nach ${stayName} zurück. Tausche ein sicheres Ende nicht gegen einen späten Wechsel zu ${secondary} oder einen unbestätigten Straßenhorizont.`), sourceIds: ids },
    ] },
  };
  return {
    version: 1, id: `${item.id}-one-site-night`, slug: `${item.id}-one-site-night`, destinationId: item.id, recommendedSiteId: item.sites[0][0],
    title: item.title,
    seoDescription: bi(`Follow a sourced one-site stargazing route from ${stayName} to ${primary}, with daylight arrival, current-condition checks and a direct return.`, `Folge einer belegten Ein-Ort-Stargazing-Route von ${stayName} zu ${primary}, mit Tageslicht-Ankunft, aktueller Prüfung und direkter Rückkehr.`),
    standfirst: bi(`${item.route.en} This self-guided route uses ${primary} as the fixed site and ${stayName} as the return base. ${item.constraint.en} The plan therefore values a verified entrance, an early arrival and an uneventful journey home more than an extra stop.`, `${item.route.de} Diese selbst geführte Route nutzt ${primary} als festen Ort und ${stayName} als Rückkehrbasis. ${item.constraint.de} Der Plan bewertet deshalb bestätigten Zugang, frühe Ankunft und eine ereignislose Heimfahrt höher als einen zusätzlichen Stopp.`),
    facts: [
      { label: bi("Chosen site", "Gewählter Ort"), value: bi(primary, primary), sourceIds: ids },
      { label: bi("Base", "Basis"), value: bi(stayName, stayName), sourceIds: ids },
      { label: bi("Arrival", "Ankunft"), value: bi("Before sunset, after a same-day access check", "Vor Sonnenuntergang nach Zugangskontrolle am selben Tag"), sourceIds: ids },
      { label: bi("Alternative", "Alternative"), value: bi(`${secondary}, only as a separately verified plan`, `${secondary}, nur als separat geprüfter Plan`), sourceIds: ids },
    ],
    blocks: orders[index % orders.length].map((kind) => blocks[kind]), sourceIds: ids, lastReviewedAt: "2026-08-31",
  };
}

const destinations = read("data-config/sources/destinations.json");
const sites = read("data-config/sources/observation-sites.json");
const stays = read("data-config/sources/stay-areas.json");
const destinationImages = read("data-config/sources/destination-images.json");
const siteImages = read("data-config/sources/site-images.json");
const guides = read("data-config/editorial/destination-guides.json");
const tours = read("data-config/editorial/location-tours.json");

const append = (array, item, key = "id") => {
  const index = array.findIndex((existing) => existing[key] === item[key]);
  if (index === -1) array.push(item);
  else array[index] = item;
};

for (const [index, item] of candidates.entries()) {
  const observationSiteIds = item.sites.map((site) => site[0]);
  append(destinations, { id: item.id, slug: item.id, name: item.name, countryCode: item.countryCode, countryName: item.countryName, continent: item.continent, regionSlugs: item.regions, timezone: item.timezone, active: true, priority: item.priority, tags: item.tags, observationSiteIds, stayAreaIds: [item.stay[0]], affiliateQuery: item.affiliateQuery });
  for (const site of item.sites) {
    const [id,name,lat,lon,elevationM,siteType,publicAccess,accessScore,notesSourceUrl] = site;
    append(sites, { id, slug: id, destinationId: item.id, name, lat, lon, elevationM, siteType, publicAccess, accessScore, active: true, priority: item.priority, certificationIds: [], notesSourceUrl,
      accessNotes: bi(`Use only the published visitor arrangement for ${name}. Confirm current access, parking or booking, hours and hazard notices before travel; the coordinate is not permission to enter or camp.`, `Nutze nur die veröffentlichte Besucherregelung für ${name}. Bestätige aktuellen Zugang, Parken oder Buchung, Zeiten und Gefahrenmeldungen vor der Reise; die Koordinate ist keine Zutritts- oder Campingerlaubnis.`) });
    append(siteImages, { slug: id, status: "pending", overrideReason: "Awaiting a fully attributed CC0, CC BY, CC BY-SA, public-domain, or government-work image." }, "slug");
  }
  append(stays, { id: item.stay[0], destinationId: item.id, name: item.stay[1], lat: item.stay[2], lon: item.stay[3], affiliateQuery: `${item.stay[1]} ${item.countryName}`, observationSiteIds });
  append(destinationImages, { slug: item.id, status: "pending", overrideReason: "Awaiting a fully attributed CC0, CC BY, CC BY-SA, public-domain, or government-work image." }, "slug");
  append(guides, guideFor(item, index), "slug");
  append(tours, tourFor(item, index), "slug");
}

write("data-config/sources/destinations.json", destinations);
write("data-config/sources/observation-sites.json", sites);
write("data-config/sources/stay-areas.json", stays);
write("data-config/sources/destination-images.json", destinationImages);
write("data-config/sources/site-images.json", siteImages);
write("data-config/editorial/destination-guides.json", guides);
write("data-config/editorial/location-tours.json", tours);

console.log(`Expanded catalog to ${destinations.length} destinations, ${sites.length} sites, ${guides.length} guides and ${tours.length} tours.`);

export { candidates, bi, read, write, root };
